<?php
require 'config.php';require 'protecao.php';require 'campanha_lib.php';if(!defined('TENANT_ID'))die('Tenant não identificado.');
if($_SERVER['REQUEST_METHOD']==='POST'){$ok=['novo','separando','saiu_entrega','entregue','cancelado'];$status=$_POST['status']??'novo';if(!in_array($status,$ok,true))$status='novo';$pdo->prepare("UPDATE campanha_solicitacoes_materiais SET status=? WHERE id=? AND tenant_id=?")->execute([$status,(int)$_POST['id'],TENANT_ID]);header('Location: admin_campanha_solicitacoes.php');exit;}
$s=$pdo->prepare("SELECT * FROM campanha_solicitacoes_materiais WHERE tenant_id=? ORDER BY id DESC LIMIT 1000");$s->execute([TENANT_ID]);$lista=$s->fetchAll(PDO::FETCH_ASSOC);
?>
<!doctype html><html lang="pt-br"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Solicitações</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><div class="container py-4"><div class="d-flex justify-content-between mb-3"><h3>Solicitações de Material</h3><a href="admin_campanha.php" class="btn btn-outline-secondary">Voltar</a></div><div class="card border-0 shadow-sm rounded-4"><div class="card-body"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Solicitante</th><th>Endereço</th><th>Itens</th><th>Status</th></tr></thead><tbody><?php foreach($lista as $r):?><tr><td><strong><?= campanha_h($r['nome']) ?></strong><div><?= campanha_h($r['whatsapp']) ?></div></td><td><?= campanha_h($r['endereco']) ?>, <?= campanha_h($r['numero']) ?><div class="small"><?= campanha_h($r['bairro']) ?> - <?= campanha_h($r['cidade']) ?>/<?= campanha_h($r['uf']) ?></div></td><td><?= campanha_h($r['itens']) ?></td><td><form method="post" class="d-flex gap-2"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><select name="status" class="form-select form-select-sm"><?php foreach(['novo'=>'Novo','separando'=>'Separando','saiu_entrega'=>'Saiu para entrega','entregue'=>'Entregue','cancelado'=>'Cancelado'] as $v=>$l):?><option value="<?= $v ?>" <?= $r['status']===$v?'selected':'' ?>><?= $l ?></option><?php endforeach;?></select><button class="btn btn-sm btn-primary">Salvar</button></form></td></tr><?php endforeach;?></tbody></table></div></div></div></div></body></html>
